"""Cocotb system test for the RTL generated by Vitis HLS.

The test deliberately does not call the C++ accelerator.  It drives the
generated RTL exactly like a Zynq PS would:

* AXI-Lite writes configure the input/output pointers and FAST parameters.
* Two AXI4 RAM models stand in for the external DDR ports.
* Random memory stalls exercise valid/ready and burst handling.
* The output corner map is compared byte-for-byte with the Vitis Vision
  C-model golden file produced from the same real bookshelf image.
"""
from pathlib import Path

import cocotb
from cocotb.clock import Clock
from cocotb.triggers import ClockCycles, RisingEdge

from common.axi_ram import AxiRamModel


ROOT = Path(__file__).resolve().parents[1]
HLS_BUILD = ROOT / "panorama" / "hls_fast" / "build"

WIDTH = 160
HEIGHT = 96
THRESHOLD = 20
FRAME_BYTES = WIDTH * HEIGHT
INPUT_ADDRESS = 0x0010_0000
OUTPUT_ADDRESS = 0x0020_0000


def _signal(dut, name):
    """Resolve a generated port without depending on simulator case rules."""
    for candidate in (name, name.lower(), name.upper()):
        try:
            return getattr(dut, candidate)
        except AttributeError:
            pass
    raise AttributeError("DUT signal not found: {}".format(name))


class AxiLiteMaster:
    """Small dependency-free AXI4-Lite master used as the simulated PS."""

    def __init__(self, dut, prefix, clock):
        self.clock = clock
        for suffix in (
            "AWVALID", "AWREADY", "AWADDR", "WVALID", "WREADY",
            "WDATA", "WSTRB", "BVALID", "BREADY", "BRESP",
            "ARVALID", "ARREADY", "ARADDR", "RVALID", "RREADY",
            "RDATA", "RRESP",
        ):
            setattr(self, suffix.lower(), _signal(dut, prefix + "_" + suffix))

        self.awvalid.value = 0
        self.awaddr.value = 0
        self.wvalid.value = 0
        self.wdata.value = 0
        self.wstrb.value = 0
        self.bready.value = 1
        self.arvalid.value = 0
        self.araddr.value = 0
        self.rready.value = 1

    async def write(self, address, data, strobe=0xF, timeout_cycles=100):
        self.awaddr.value = address
        self.awvalid.value = 1
        self.wdata.value = data
        self.wstrb.value = strobe
        self.wvalid.value = 1

        address_done = False
        data_done = False
        for _ in range(timeout_cycles):
            await RisingEdge(self.clock)
            if not address_done and int(self.awready.value):
                address_done = True
                self.awvalid.value = 0
            if not data_done and int(self.wready.value):
                data_done = True
                self.wvalid.value = 0
            if address_done and data_done:
                break
        else:
            raise TimeoutError("AXI-Lite write address/data handshake timed out")

        for _ in range(timeout_cycles):
            await RisingEdge(self.clock)
            if int(self.bvalid.value):
                response = int(self.bresp.value)
                assert response == 0, "AXI-Lite write BRESP={}".format(response)
                return
        raise TimeoutError("AXI-Lite write response timed out")

    async def read(self, address, timeout_cycles=100):
        self.araddr.value = address
        self.arvalid.value = 1

        for _ in range(timeout_cycles):
            await RisingEdge(self.clock)
            if int(self.arready.value):
                self.arvalid.value = 0
                break
        else:
            raise TimeoutError("AXI-Lite read address handshake timed out")

        for _ in range(timeout_cycles):
            await RisingEdge(self.clock)
            if int(self.rvalid.value):
                response = int(self.rresp.value)
                value = int(self.rdata.value)
                assert response == 0, "AXI-Lite read RRESP={}".format(response)
                return value
        raise TimeoutError("AXI-Lite read response timed out")


def _drive_axi_sidebands(dut, prefix):
    # The generic RAM model supplies the required AXI response channels.
    # HLS also exposes optional ID/USER response inputs; this design uses ID 0.
    for suffix in ("RID", "RUSER", "BID", "BUSER"):
        _signal(dut, prefix + "_" + suffix).value = 0


@cocotb.test()
async def hls_generated_fast_nms_matches_vitis_vision_golden(dut):
    input_bytes = (HLS_BUILD / "input_gray_160x96.raw").read_bytes()
    expected = (HLS_BUILD / "fast_output_csim.raw").read_bytes()
    assert len(input_bytes) == FRAME_BYTES
    assert len(expected) == FRAME_BYTES

    cocotb.start_soon(Clock(dut.ap_clk, 10, unit="ns").start())

    _drive_axi_sidebands(dut, "m_axi_gmem0")
    _drive_axi_sidebands(dut, "m_axi_gmem1")

    input_ram = AxiRamModel(
        dut,
        "m_axi_gmem0",
        dut.ap_clk,
        dut.ap_rst_n,
        size=0x10000,
        base_address=INPUT_ADDRESS,
        stall_probability=0.15,
        read_latency=(0, 5),
        write_response_latency=(0, 3),
        seed=20260829,
        reset_active_level=0,
    )
    output_ram = AxiRamModel(
        dut,
        "m_axi_gmem1",
        dut.ap_clk,
        dut.ap_rst_n,
        size=0x10000,
        base_address=OUTPUT_ADDRESS,
        stall_probability=0.15,
        read_latency=(0, 5),
        write_response_latency=(0, 5),
        seed=20260830,
        reset_active_level=0,
    )
    input_ram.write(INPUT_ADDRESS, input_bytes)
    input_ram.start()
    output_ram.start()

    control = AxiLiteMaster(dut, "s_axi_control", dut.ap_clk)
    pointers = AxiLiteMaster(dut, "s_axi_control_r", dut.ap_clk)

    dut.ap_rst_n.value = 0
    await ClockCycles(dut.ap_clk, 10)
    dut.ap_rst_n.value = 1
    await ClockCycles(dut.ap_clk, 4)

    # Pointer registers are 64-bit values split into two 32-bit AXI-Lite words.
    await pointers.write(0x10, INPUT_ADDRESS & 0xFFFF_FFFF)
    await pointers.write(0x14, INPUT_ADDRESS >> 32)
    await pointers.write(0x1C, OUTPUT_ADDRESS & 0xFFFF_FFFF)
    await pointers.write(0x20, OUTPUT_ADDRESS >> 32)

    await control.write(0x10, THRESHOLD)
    await control.write(0x18, HEIGHT)
    await control.write(0x20, WIDTH)
    await control.write(0x00, 1)  # ap_start

    elapsed_cycles = 0
    status = 0
    while elapsed_cycles < 100_000:
        await ClockCycles(dut.ap_clk, 250)
        elapsed_cycles += 250
        status = await control.read(0x00)
        if status & 0x2:  # ap_done (clear-on-read)
            break
    else:
        raise TimeoutError(
            "HLS FAST+NMS did not finish after {} cycles; status=0x{:08x}".format(
                elapsed_cycles, status
            )
        )

    actual = output_ram.read(OUTPUT_ADDRESS, FRAME_BYTES)
    mismatches = [
        index
        for index, (rtl_value, golden_value) in enumerate(zip(actual, expected))
        if rtl_value != golden_value
    ]

    artifact_dir = ROOT / "panorama" / "build" / "hls_fast_cocotb"
    artifact_dir.mkdir(parents=True, exist_ok=True)
    (artifact_dir / "fast_output_rtl.raw").write_bytes(actual)
    (artifact_dir / "report.txt").write_text(
        "simulator=cocotb+generated RTL\n"
        "image={}x{}\n"
        "threshold={}\n"
        "completed_by_cycle={}\n"
        "corner_pixels={}\n"
        "byte_mismatches={}\n".format(
            WIDTH,
            HEIGHT,
            THRESHOLD,
            elapsed_cycles,
            sum(value != 0 for value in actual),
            len(mismatches),
        ),
        encoding="utf-8",
    )

    assert not mismatches, (
        "generated RTL differs from Vitis Vision golden at {} pixels; first={}"
        .format(len(mismatches), mismatches[:16])
    )
    assert sum(value != 0 for value in actual) == 418

    dut._log.info(
        "Vitis HLS RTL PASS: %d bytes exact, 418 corners, random AXI stalls, <=%d cycles",
        FRAME_BYTES,
        elapsed_cycles,
    )

